/**
 * Unit tests for the dependency-free ZIP reader/writer in `lib/zip.js`.
 *
 * Run from the package root:
 *
 *   node --test test/zip.test.mjs
 *
 * The committed fixture `test/fixtures/compress-archive.zip` was generated by
 * PowerShell `Compress-Archive` from `test/fixtures/archive-src/`, so reading a
 * real-world archive is covered deterministically even when PowerShell is not
 * available at test time. The streaming (data-descriptor, fflate-style)
 * archives are assembled byte by byte below, independently of the module under
 * test, and deliberately carry zeros in the local file headers.
 */

import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { mkdir, mkdtemp, readdir, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import * as zlib from 'node:zlib';

import { ZIP_READ_LIMITS, crc32, readZipEntries, writeZipEntries } from '../lib/zip.js';

const FIXTURE_ARCHIVE = new URL('./fixtures/compress-archive.zip', import.meta.url);
const FIXTURE_SOURCE_ROOT = fileURLToPath(new URL('./fixtures/archive-src/', import.meta.url));

const ZIP_LOCAL_SIGNATURE = 0x04034b50;
const ZIP_CENTRAL_SIGNATURE = 0x02014b50;
const ZIP_EOCD_SIGNATURE = 0x06054b50;
const ZIP_DATA_DESCRIPTOR_SIGNATURE = 0x08074b50;
const UTF8_FLAG = 0x0800;
const DATA_DESCRIPTOR_FLAG = 0x0008;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Small deterministic PRNG so "random" payloads are reproducible across runs.
 * @param {number} seed - 32-bit seed.
 * @returns {() => number} generator returning numbers in [0, 1).
 */
function mulberry32(seed) {
  let state = seed >>> 0;
  return function next() {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Deterministic pseudo-random bytes, including incompressible ones.
 * @param {number} length - byte count.
 * @param {number} seed - PRNG seed.
 * @returns {Buffer} generated bytes.
 */
function randomBytes(length, seed) {
  const buffer = Buffer.alloc(length);
  const next = mulberry32(seed);
  for (let index = 0; index < length; index += 1) {
    buffer[index] = Math.floor(next() * 256);
  }
  return buffer;
}

/**
 * Quote a value as a PowerShell single-quoted string literal.
 * @param {string} value - raw value.
 * @returns {string} quoted literal.
 */
function psQuote(value) {
  return `'${value.replace(/'/g, "''")}'`;
}

/** @type {{ checked: boolean, executable: string | null }} */
let powerShellProbe = { checked: false, executable: null };

/**
 * Locate a PowerShell executable for the optional real-world interop tests.
 * @returns {string | null} executable name or absolute path, null when absent.
 */
function findPowerShell() {
  if (powerShellProbe.checked) return powerShellProbe.executable;
  powerShellProbe = { checked: true, executable: null };
  const candidates = ['pwsh', 'powershell'];
  if (process.platform === 'win32') {
    const systemRoot = process.env.SystemRoot ?? process.env.windir ?? 'C:\\Windows';
    candidates.push(
      path.join(systemRoot, 'System32', 'WindowsPowerShell', 'v1.0', 'powershell.exe'),
    );
    const programFiles = process.env.ProgramFiles ?? 'C:\\Program Files';
    candidates.push(path.join(programFiles, 'PowerShell', '7', 'pwsh.exe'));
  }
  for (const candidate of candidates) {
    const probe = spawnSync(
      candidate,
      ['-NoProfile', '-NonInteractive', '-Command', 'exit 0'],
      { encoding: 'utf8', timeout: 30000 },
    );
    if (probe.status === 0) {
      powerShellProbe.executable = candidate;
      return candidate;
    }
  }
  return null;
}

/**
 * List every regular file below a directory, recursively.
 * @param {string} directory - absolute directory path.
 * @returns {Promise<string[]>} absolute file paths.
 */
async function listFilesRecursive(directory) {
  const result = [];
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const absolute = path.join(directory, entry.name);
    if (entry.isDirectory()) result.push(...(await listFilesRecursive(absolute)));
    else if (entry.isFile()) result.push(absolute);
  }
  return result;
}

/**
 * Expected entries of the committed Compress-Archive fixture, read from the
 * committed source directory it was generated from.
 * @returns {Promise<Map<string, Buffer>>} entry name (forward slashes) to bytes.
 */
async function readExpectedFixtureEntries() {
  const expected = new Map();
  for (const absolute of await listFilesRecursive(FIXTURE_SOURCE_ROOT)) {
    const relative = path.relative(FIXTURE_SOURCE_ROOT, absolute).split(path.sep).join('/');
    expected.set(relative, await readFile(absolute));
  }
  return expected;
}

/**
 * Assert that `readZipEntries` returned exactly the expected name → bytes map.
 * @param {Array<{name: string, data: Uint8Array}>} actual - reader output.
 * @param {Map<string, Buffer | Uint8Array>} expected - expected entries.
 */
function assertSameEntries(actual, expected) {
  assert.ok(Array.isArray(actual), 'readZipEntries 必须返回数组');
  const actualNames = actual.map((entry) => entry.name);
  assert.equal(
    actual.length,
    expected.size,
    `条目数量不一致；实际条目：${actualNames.join(', ')}`,
  );
  const actualMap = new Map(actual.map((entry) => [entry.name, entry.data]));
  for (const [name, data] of expected) {
    assert.ok(actualMap.has(name), `缺少条目 "${name}"；实际条目：${actualNames.join(', ')}`);
    const actualData = actualMap.get(name);
    assert.ok(actualData instanceof Uint8Array, `条目 "${name}" 的 data 必须是 Uint8Array`);
    assert.ok(
      Buffer.from(actualData).equals(Buffer.from(data)),
      `条目 "${name}" 的内容与预期不一致`,
    );
  }
  for (const name of actualNames) {
    assert.ok(expected.has(name), `多出条目 "${name}"`);
  }
}

/**
 * Assert that a callback throws an Error with the given code and a readable
 * message (never a bare string), optionally matching a message pattern.
 * @param {() => unknown} callback - throwing callback.
 * @param {string} code - expected `error.code`.
 * @param {RegExp} [messageMatcher] - optional message assertion.
 */
function assertZipError(callback, code, messageMatcher) {
  assert.throws(callback, (error) => {
    assert.ok(error instanceof Error, '抛出的必须是 Error 实例，不能是裸字符串');
    assert.equal(
      error.code,
      code,
      `错误码应为 ${code}，实际为 ${String(error.code)}（消息：${String(error.message)}）`,
    );
    assert.equal(typeof error.message, 'string');
    assert.ok(error.message.trim().length > 0, '错误消息不能为空');
    if (messageMatcher !== undefined) assert.match(error.message, messageMatcher);
    return true;
  });
}

/**
 * Parse the EOCD and central directory of a ZIP produced by this module (no
 * archive comment). Test-side parser, independent of `readZipEntries`.
 * @param {Buffer} zip - complete archive bytes.
 * @returns {{eocd: {offset: number, entryCount: number, directorySize: number, directoryOffset: number}, headers: Array<object>}} parsed structures.
 */
function readCentralHeaders(zip) {
  assert.ok(zip.length >= 22, 'ZIP 至少要有 22 字节');
  const eocdOffset = zip.length - 22;
  assert.equal(
    zip.readUInt32LE(eocdOffset),
    ZIP_EOCD_SIGNATURE,
    'EOCD 应位于文件末尾（本测试的 ZIP 没有注释）',
  );
  const entryCount = zip.readUInt16LE(eocdOffset + 10);
  const directorySize = zip.readUInt32LE(eocdOffset + 12);
  const directoryOffset = zip.readUInt32LE(eocdOffset + 16);
  const headers = [];
  let offset = directoryOffset;
  for (let index = 0; index < entryCount; index += 1) {
    assert.equal(zip.readUInt32LE(offset), ZIP_CENTRAL_SIGNATURE);
    const nameLength = zip.readUInt16LE(offset + 28);
    const extraLength = zip.readUInt16LE(offset + 30);
    const commentLength = zip.readUInt16LE(offset + 32);
    headers.push({
      offset,
      name: zip.toString('utf8', offset + 46, offset + 46 + nameLength),
      nameLength,
      flags: zip.readUInt16LE(offset + 8),
      method: zip.readUInt16LE(offset + 10),
      crc: zip.readUInt32LE(offset + 16),
      compressedSize: zip.readUInt32LE(offset + 20),
      uncompressedSize: zip.readUInt32LE(offset + 24),
      localHeaderOffset: zip.readUInt32LE(offset + 42),
    });
    offset += 46 + nameLength + extraLength + commentLength;
  }
  return { eocd: { offset: eocdOffset, entryCount, directorySize, directoryOffset }, headers };
}

/**
 * Offset of the payload bytes of one locally stored entry (uses the local
 * header's name/extra lengths, exactly as a robust reader must).
 * @param {Buffer} zip - archive bytes.
 * @param {{localHeaderOffset: number}} header - central directory header.
 * @returns {number} payload offset.
 */
function localPayloadOffset(zip, header) {
  const local = header.localHeaderOffset;
  assert.equal(zip.readUInt32LE(local), ZIP_LOCAL_SIGNATURE);
  return local + 30 + zip.readUInt16LE(local + 26) + zip.readUInt16LE(local + 28);
}

/**
 * Apply byte patches to a copy of a buffer.
 * @param {Buffer} buffer - original bytes.
 * @param {(copy: Buffer) => void} mutate - patch callback.
 * @returns {Buffer} patched copy.
 */
function copyWithPatches(buffer, mutate) {
  const copy = Buffer.from(buffer);
  mutate(copy);
  return copy;
}

/**
 * Build a ZIP file byte by byte, without using the module under test.
 *
 * Supports the standard layout and the streaming layout that fflate produces:
 * flag bit 3 set, CRC/size fields in the local header left at zero, and a data
 * descriptor after the payload whose authoritative counterpart lives in the
 * central directory.
 *
 * @param {Array<{name: string, data?: Buffer | Uint8Array, method?: 'deflate' | 'store'}>} entries - entries to write.
 * @param {{dataDescriptor?: boolean, descriptorSignature?: boolean, zeroLocalHeaderFields?: boolean}} [options] - layout knobs.
 * @returns {Buffer} archive bytes.
 */
function buildManualZip(entries, options = {}) {
  const {
    dataDescriptor = false,
    descriptorSignature = true,
    zeroLocalHeaderFields = false,
  } = options;
  const parts = [];
  const centralParts = [];
  let offset = 0;
  for (const entry of entries) {
    const nameBytes = Buffer.from(entry.name, 'utf8');
    const data = Buffer.from(entry.data ?? Buffer.alloc(0));
    const method = entry.method === 'store' ? 0 : 8;
    const payload = method === 0 ? data : zlib.deflateRawSync(data);
    const checksum = crc32(data);
    const flags = UTF8_FLAG | (dataDescriptor ? DATA_DESCRIPTOR_FLAG : 0);
    const zeroSizes = dataDescriptor || zeroLocalHeaderFields;

    const local = Buffer.alloc(30 + nameBytes.length);
    local.writeUInt32LE(ZIP_LOCAL_SIGNATURE, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(flags, 6);
    local.writeUInt16LE(method, 8);
    local.writeUInt16LE(0, 10);
    local.writeUInt16LE(0x21, 12);
    local.writeUInt32LE(zeroSizes ? 0 : checksum, 14);
    local.writeUInt32LE(zeroSizes ? 0 : payload.length, 18);
    local.writeUInt32LE(zeroSizes ? 0 : data.length, 22);
    local.writeUInt16LE(nameBytes.length, 26);
    local.writeUInt16LE(0, 28);
    nameBytes.copy(local, 30);
    parts.push(local, payload);

    let descriptorLength = 0;
    if (dataDescriptor) {
      const descriptor = Buffer.alloc(descriptorSignature ? 16 : 12);
      let cursor = 0;
      if (descriptorSignature) {
        descriptor.writeUInt32LE(ZIP_DATA_DESCRIPTOR_SIGNATURE, 0);
        cursor = 4;
      }
      descriptor.writeUInt32LE(checksum, cursor);
      descriptor.writeUInt32LE(payload.length, cursor + 4);
      descriptor.writeUInt32LE(data.length, cursor + 8);
      parts.push(descriptor);
      descriptorLength = descriptor.length;
    }

    const central = Buffer.alloc(46 + nameBytes.length);
    central.writeUInt32LE(ZIP_CENTRAL_SIGNATURE, 0);
    central.writeUInt16LE(20, 4);
    central.writeUInt16LE(20, 6);
    central.writeUInt16LE(flags, 8);
    central.writeUInt16LE(method, 10);
    central.writeUInt16LE(0, 12);
    central.writeUInt16LE(0x21, 14);
    central.writeUInt32LE(checksum, 16);
    central.writeUInt32LE(payload.length, 20);
    central.writeUInt32LE(data.length, 24);
    central.writeUInt16LE(nameBytes.length, 28);
    central.writeUInt16LE(0, 30);
    central.writeUInt16LE(0, 32);
    central.writeUInt16LE(0, 34);
    central.writeUInt16LE(0, 36);
    central.writeUInt32LE(0, 38);
    central.writeUInt32LE(offset, 42);
    nameBytes.copy(central, 46);
    centralParts.push(central);

    offset += local.length + payload.length + descriptorLength;
  }
  const directory = Buffer.concat(centralParts);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(ZIP_EOCD_SIGNATURE, 0);
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(directory.length, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);
  return Buffer.concat([...parts, directory, eocd]);
}

/** Entries used by the streaming / hand-built archive tests. */
const STREAMING_ENTRIES = [
  {
    name: 'session.v4.jsonl',
    data: Buffer.from('{"type":"session","version":1}\n' + 'tick\n'.repeat(64)),
  },
  { name: 'media/streamed.bin', data: randomBytes(4096, 21) },
  { name: 'files/ab/cd/notes:stream.txt', data: Buffer.from('streamed attachment\n') },
  { name: 'stored.bin', data: randomBytes(512, 3), method: 'store' },
];

/** Mixed entries used by several round-trip tests. */
const ROUND_TRIP_ENTRIES = [
  { name: 'session.v4.jsonl', data: Buffer.from('{"type":"session","id":"abc"}\n{"type":"message"}\n') },
  { name: 'media/attachment-0a1b2c.png', data: randomBytes(8192, 11) },
  {
    name: 'files/de/deadbeef01234567/report:final.txt',
    data: Buffer.from('a colon in an entry name stays inside the archive\n'),
  },
  { name: '中文目录/会话.jsonl', data: Buffer.from('{"内容":"中文内容","emoji":"🐋"}\n') },
  { name: 'empty.bin', data: Buffer.alloc(0) },
  { name: 'nested/deep/dir/file.txt', data: Buffer.from('deep\n') },
];

/**
 * Expected map for a list of entries.
 * @param {Array<{name: string, data: Buffer | Uint8Array}>} entries - entries.
 * @returns {Map<string, Buffer>} name to bytes.
 */
function toExpectedMap(entries) {
  return new Map(entries.map((entry) => [entry.name, Buffer.from(entry.data)]));
}

// ---------------------------------------------------------------------------
// crc32
// ---------------------------------------------------------------------------

test('crc32: known test vectors', () => {
  assert.equal(crc32(Buffer.alloc(0)), 0);
  assert.equal(crc32(Buffer.from('123456789')), 0xcbf43926);
  assert.equal(crc32(Buffer.from('a')), 0xe8b7be43);
  assert.equal(
    crc32(Buffer.from('The quick brown fox jumps over the lazy dog')),
    0x414fa339,
  );
});

test('crc32: matches node:zlib reference implementation', () => {
  if (typeof zlib.crc32 !== 'function') return; // older Node without zlib.crc32
  for (const length of [0, 1, 2, 3, 7, 31, 1000, 65537]) {
    const bytes = randomBytes(length, 0x1234 + length);
    assert.equal(crc32(bytes), zlib.crc32(bytes), `CRC mismatch for length ${length}`);
  }
});

test('crc32: accepts a Uint8Array view and rejects non-binary input', () => {
  const padded = Buffer.concat([Buffer.from('skip'), Buffer.from('123456789')]);
  const view = new Uint8Array(padded.buffer, padded.byteOffset + 4, 9);
  assert.equal(crc32(view), 0xcbf43926);
  assertZipError(() => crc32('not bytes'), 'INVALID_ARGUMENT');
  assertZipError(() => crc32(null), 'INVALID_ARGUMENT');
});

// ---------------------------------------------------------------------------
// write → read round-trip
// ---------------------------------------------------------------------------

test('write → read round-trip: mixed multi-entry archive', () => {
  const zip = writeZipEntries(ROUND_TRIP_ENTRIES);
  assert.ok(zip instanceof Buffer);
  assert.equal(zip.readUInt32LE(0), ZIP_LOCAL_SIGNATURE);
  const entries = readZipEntries(zip);
  assertSameEntries(entries, toExpectedMap(ROUND_TRIP_ENTRIES));
});

test('write → read round-trip: store compression', () => {
  const zip = writeZipEntries(ROUND_TRIP_ENTRIES, { compression: 'store' });
  const { headers } = readCentralHeaders(zip);
  assert.equal(headers.length, ROUND_TRIP_ENTRIES.length);
  for (const [index, header] of headers.entries()) {
    assert.equal(header.method, 0, 'store 模式必须使用压缩方法 0');
    assert.equal(header.compressedSize, ROUND_TRIP_ENTRIES[index].data.length);
    assert.equal(header.uncompressedSize, ROUND_TRIP_ENTRIES[index].data.length);
  }
  assertSameEntries(readZipEntries(zip), toExpectedMap(ROUND_TRIP_ENTRIES));
});

test('write → read round-trip: empty archive', () => {
  const zip = writeZipEntries([]);
  assert.equal(zip.length, 22, '空 ZIP 只有 22 字节 EOCD');
  assert.equal(zip.readUInt32LE(0), ZIP_EOCD_SIGNATURE);
  assert.deepEqual(readZipEntries(zip), []);
});

test('write → read round-trip: binary random payload is byte exact', () => {
  const payload = randomBytes(65536, 42);
  const zip = writeZipEntries([{ name: 'random.bin', data: payload }]);
  const entries = readZipEntries(zip);
  assert.equal(entries.length, 1);
  assert.ok(Buffer.from(entries[0].data).equals(payload), '二进制内容往返后必须完全一致');
});

test('write → read round-trip: payload larger than 1 MiB', () => {
  const incompressible = randomBytes(2 * 1024 * 1024 + 17, 424242);
  const compressible = Buffer.from('A'.repeat(1_500_000));
  const zip = writeZipEntries([
    { name: 'large/random.bin', data: incompressible },
    { name: 'large/repeated.txt', data: compressible },
  ]);
  const entries = readZipEntries(zip);
  assertSameEntries(entries, new Map([
    ['large/random.bin', incompressible],
    ['large/repeated.txt', compressible],
  ]));
  assert.ok(zip.length < incompressible.length + compressible.length, 'deflate 应至少压缩掉重复内容');
});

test('read: accepts both Buffer and plain Uint8Array input', () => {
  const zip = writeZipEntries(ROUND_TRIP_ENTRIES);
  const fromBuffer = readZipEntries(zip);
  const fromUint8Array = readZipEntries(new Uint8Array(zip));
  assertSameEntries(fromUint8Array, toExpectedMap(ROUND_TRIP_ENTRIES));
  assertSameEntries(fromBuffer, toExpectedMap(ROUND_TRIP_ENTRIES));

  // A view with a non-zero byteOffset must be handled by offset, not by
  // assuming the array starts at the beginning of its backing ArrayBuffer.
  const padded = Buffer.concat([Buffer.alloc(8), zip]);
  const view = new Uint8Array(padded.buffer, padded.byteOffset + 8, zip.length);
  assertSameEntries(readZipEntries(view), toExpectedMap(ROUND_TRIP_ENTRIES));
});

test('write: produces standard headers, CRC-32 values, and EOCD layout', () => {
  const entries = [
    { name: 'plain.txt', data: Buffer.from('hello zip\n') },
    { name: '中文.txt', data: Buffer.from('中文内容\n') },
  ];
  const zip = writeZipEntries(entries);
  const { eocd, headers } = readCentralHeaders(zip);
  assert.equal(eocd.entryCount, entries.length);
  assert.equal(eocd.directoryOffset + eocd.directorySize, eocd.offset, '中央目录后应紧跟 EOCD');
  assert.deepEqual(headers.map((header) => header.name), entries.map((entry) => entry.name));
  for (const [index, header] of headers.entries()) {
    const expected = entries[index];
    const nameLength = Buffer.byteLength(expected.name, 'utf8');
    assert.equal(header.flags & UTF8_FLAG, UTF8_FLAG, '本地头必须带 UTF-8 文件名标志（bit 11）');
    assert.equal(header.method, 8, '默认使用 deflate');
    assert.equal(header.crc, crc32(expected.data));
    assert.equal(header.compressedSize, zlib.deflateRawSync(expected.data).length);
    assert.equal(header.uncompressedSize, expected.data.length);
    assert.equal(header.nameLength, nameLength);

    const local = header.localHeaderOffset;
    assert.equal(zip.readUInt32LE(local), ZIP_LOCAL_SIGNATURE);
    assert.equal(zip.readUInt16LE(local + 4), 20, '本地头版本应为 20');
    assert.equal(zip.readUInt16LE(local + 6) & UTF8_FLAG, UTF8_FLAG);
    assert.equal(zip.readUInt16LE(local + 8), header.method);
    assert.equal(zip.readUInt32LE(local + 14), header.crc);
    assert.equal(zip.readUInt32LE(local + 18), header.compressedSize);
    assert.equal(zip.readUInt32LE(local + 22), header.uncompressedSize);
    assert.equal(zip.readUInt16LE(local + 26), nameLength);
    assert.equal(zip.readUInt16LE(local + 28), 0);
    const payloadStart = localPayloadOffset(zip, header);
    assert.ok(
      zip.subarray(payloadStart, payloadStart + header.compressedSize)
        .equals(zlib.deflateRawSync(expected.data)),
      '本地头之后应紧跟 deflate 数据',
    );
  }
});

test('write: duplicate names are written and last occurrence wins on read', () => {
  const zip = writeZipEntries([
    { name: 'same.txt', data: Buffer.from('first') },
    { name: 'same.txt', data: Buffer.from('second') },
  ]);
  assert.equal(readCentralHeaders(zip).headers.length, 2, '写入端不应去重');
  const entries = readZipEntries(zip);
  assert.equal(entries.length, 1);
  assert.equal(entries[0].name, 'same.txt');
  assert.equal(Buffer.from(entries[0].data).toString('utf8'), 'second');
});

test('write: rejects invalid arguments with readable coded errors', () => {
  assertZipError(() => writeZipEntries('nope'), 'INVALID_ARGUMENT');
  assertZipError(() => writeZipEntries([null]), 'INVALID_ARGUMENT');
  assertZipError(() => writeZipEntries([{ data: Buffer.alloc(0) }]), 'INVALID_ARGUMENT');
  assertZipError(() => writeZipEntries([{ name: '', data: Buffer.alloc(0) }]), 'INVALID_ARGUMENT');
  assertZipError(() => writeZipEntries([{ name: 'file.txt' }]), 'INVALID_ARGUMENT');
  assertZipError(
    () => writeZipEntries([{ name: 'file.txt', data: 'a string is not bytes' }]),
    'INVALID_ARGUMENT',
  );
  assertZipError(
    () => writeZipEntries([{ name: 'file.txt', data: Buffer.alloc(0) }], { compression: 'gzip' }),
    'INVALID_ARGUMENT',
  );
});

test('read: rejects invalid arguments with readable coded errors', () => {
  assertZipError(() => readZipEntries('not bytes'), 'INVALID_ARGUMENT');
  assertZipError(() => readZipEntries(null), 'INVALID_ARGUMENT');
  assertZipError(() => readZipEntries(undefined), 'INVALID_ARGUMENT');
});

// ---------------------------------------------------------------------------
// Real-world PowerShell Compress-Archive interop
// ---------------------------------------------------------------------------

test('read: committed PowerShell Compress-Archive fixture', async () => {
  const bytes = await readFile(FIXTURE_ARCHIVE);
  const actual = readZipEntries(bytes);
  const expected = await readExpectedFixtureEntries();
  assertSameEntries(actual, expected);

  const names = actual.map((entry) => entry.name);
  assert.ok(names.includes('nested/note.txt'), `应保留子目录路径；实际条目：${names.join(', ')}`);
  assert.ok(names.includes('中文说明.txt'), '应正确解码 UTF-8 文件名');
  assert.ok(names.includes('empty.txt'), '应包含空文件');

  // The fixture must genuinely be a deflate/stored ZIP, not a hand-made stub.
  const { headers } = readCentralHeaders(bytes);
  assert.equal(headers.length, expected.size);
  for (const header of headers) {
    assert.ok(header.method === 0 || header.method === 8);
  }
});

test('read: ZIP freshly generated by Compress-Archive (constructed fallback otherwise)', async (t) => {
  const sources = [
    { name: 'hello.txt', data: Buffer.from('live Compress-Archive fixture\n') },
    { name: '中文文件.txt', data: Buffer.from('实时生成的中文文件名\n') },
    { name: 'binary.bin', data: randomBytes(2048, 77) },
  ];
  const expected = toExpectedMap(sources);
  const powerShell = findPowerShell();
  if (powerShell === null) {
    t.diagnostic('未找到 PowerShell：改用手工构造的最小 deflate ZIP 验证同一读取路径');
    const zip = buildManualZip(sources);
    assertSameEntries(readZipEntries(zip), expected);
    return;
  }

  const temporaryDirectory = await mkdtemp(path.join(tmpdir(), 'dsh-session-port-ca-'));
  try {
    const sourceDirectory = path.join(temporaryDirectory, 'sources');
    await mkdir(sourceDirectory, { recursive: true });
    for (const source of sources) {
      await writeFile(path.join(sourceDirectory, source.name), source.data);
    }
    const zipPath = path.join(temporaryDirectory, 'live.zip');
    const command =
      `Compress-Archive -Path ${psQuote(path.join(sourceDirectory, '*'))} ` +
      `-DestinationPath ${psQuote(zipPath)} -CompressionLevel Optimal -Force`;
    const result = spawnSync(
      powerShell,
      ['-NoProfile', '-NonInteractive', '-Command', command],
      { encoding: 'utf8', timeout: 120000 },
    );
    if (result.status !== 0 || !existsSync(zipPath)) {
      t.diagnostic(
        `Compress-Archive 调用失败（status=${String(result.status)}）：` +
          `${String(result.stderr ?? '').trim()}；改用手工构造的最小 deflate ZIP`,
      );
      assertSameEntries(readZipEntries(buildManualZip(sources)), expected);
      return;
    }
    t.diagnostic(`Compress-Archive 由 ${powerShell} 实时生成；readZipEntries 读取成功`);
    const actual = readZipEntries(await readFile(zipPath));
    assertSameEntries(actual, expected);
  } finally {
    await rm(temporaryDirectory, { recursive: true, force: true });
  }
});

test('write: generated ZIP is extractable by PowerShell Expand-Archive', async (t) => {
  const powerShell = findPowerShell();
  if (powerShell === null) {
    t.diagnostic('未找到 PowerShell：跳过外部解压校验');
    return;
  }
  // Names must be extractable on Windows, so no ':' characters here.
  const entries = [
    { name: 'session.v4.jsonl', data: Buffer.from('{"type":"session","version":1}\n') },
    { name: 'media/attachment.png', data: randomBytes(4096, 123) },
    { name: 'files/ab/cd/report.txt', data: Buffer.from('hello from the writer\n') },
    { name: '中文.txt', data: Buffer.from('中文内容\n') },
  ];
  const zipPath = path.join(await mkdtemp(path.join(tmpdir(), 'dsh-session-port-xa-')), 'written.zip');
  const extractDirectory = path.join(path.dirname(zipPath), 'extracted');
  try {
    await writeFile(zipPath, writeZipEntries(entries));
    await mkdir(extractDirectory, { recursive: true });
    const result = spawnSync(
      powerShell,
      [
        '-NoProfile',
        '-NonInteractive',
        '-Command',
        `Expand-Archive -LiteralPath ${psQuote(zipPath)} -DestinationPath ${psQuote(extractDirectory)} -Force`,
      ],
      { encoding: 'utf8', timeout: 120000 },
    );
    assert.equal(
      result.status,
      0,
      `Expand-Archive 失败（status=${String(result.status)}）：${String(result.stderr ?? '').trim()}`,
    );
    const extracted = new Map();
    for (const absolute of await listFilesRecursive(extractDirectory)) {
      const relative = path.relative(extractDirectory, absolute).split(path.sep).join('/');
      extracted.set(relative, await readFile(absolute));
    }
    assertSameEntries(
      [...extracted].map(([name, data]) => ({ name, data })),
      toExpectedMap(entries),
    );
  } finally {
    await rm(path.dirname(zipPath), { recursive: true, force: true });
  }
});

// ---------------------------------------------------------------------------
// Streaming archives (data descriptor) — the fflate export layout
// ---------------------------------------------------------------------------

test('read: fflate-style streaming ZIP with signed data descriptor', () => {
  const zip = buildManualZip(STREAMING_ENTRIES, {
    dataDescriptor: true,
    descriptorSignature: true,
  });
  // Prove the scenario: local headers carry zeros and flag bit 3.
  assert.equal(zip.readUInt16LE(6) & DATA_DESCRIPTOR_FLAG, DATA_DESCRIPTOR_FLAG);
  assert.equal(zip.readUInt32LE(14), 0, '流式 ZIP 本地头 CRC 为 0');
  assert.equal(zip.readUInt32LE(18), 0, '流式 ZIP 本地头压缩大小为 0');
  assert.equal(zip.readUInt32LE(22), 0, '流式 ZIP 本地头原始大小为 0');

  assertSameEntries(readZipEntries(zip), toExpectedMap(STREAMING_ENTRIES));
});

test('read: streaming ZIP with unsigned data descriptor', () => {
  const zip = buildManualZip(STREAMING_ENTRIES, {
    dataDescriptor: true,
    descriptorSignature: false,
  });
  // Byte after the first payload must still be readable via the central directory.
  assertSameEntries(readZipEntries(zip), toExpectedMap(STREAMING_ENTRIES));
});

test('read: central directory is authoritative when local header fields are bogus', () => {
  const zip = buildManualZip(STREAMING_ENTRIES, {
    dataDescriptor: false,
    zeroLocalHeaderFields: true,
  });
  assert.equal(zip.readUInt32LE(14), 0);
  assert.equal(zip.readUInt32LE(18), 0);
  assertSameEntries(readZipEntries(zip), toExpectedMap(STREAMING_ENTRIES));
});

test('read: ignores directory entries and empty entry names', () => {
  const zip = buildManualZip([
    { name: 'folder/', data: Buffer.alloc(0), method: 'store' },
    { name: 'folder/file.txt', data: Buffer.from('inside\n') },
    { name: '', data: Buffer.alloc(0), method: 'store' },
    { name: 'tail.bin', data: randomBytes(64, 9) },
  ]);
  const entries = readZipEntries(zip);
  assert.deepEqual(entries.map((entry) => entry.name), ['folder/file.txt', 'tail.bin']);
  assert.equal(Buffer.from(entries[0].data).toString('utf8'), 'inside\n');
});

test('read: accepts an archive comment after the EOCD', () => {
  const zip = writeZipEntries(ROUND_TRIP_ENTRIES);
  const comment = Buffer.from('session-port archive comment');
  const withComment = Buffer.concat([zip, comment]);
  withComment.writeUInt16LE(comment.length, zip.length - 22 + 20);
  assertSameEntries(readZipEntries(withComment), toExpectedMap(ROUND_TRIP_ENTRIES));
});

// ---------------------------------------------------------------------------
// Corrupt / unsupported input
// ---------------------------------------------------------------------------

/** Base archive used by the corruption tests. */
const CORRUPTION_ENTRIES = [
  { name: 'a.txt', data: Buffer.from('alpha content for corruption tests\n') },
  { name: 'b.txt', data: Buffer.from('beta content for corruption tests\n') },
];
const CORRUPTION_ZIP = writeZipEntries(CORRUPTION_ENTRIES);
const CORRUPTION_STRUCTURE = readCentralHeaders(CORRUPTION_ZIP);
const FIRST_HEADER = CORRUPTION_STRUCTURE.headers[0];
const SECOND_HEADER = CORRUPTION_STRUCTURE.headers[1];

test('read: rejects non-ZIP input', () => {
  assertZipError(() => readZipEntries(Buffer.from('{"this":"is not a zip"}')), 'EOCD_NOT_FOUND');
  assertZipError(() => readZipEntries(Buffer.from('PK')), 'EOCD_NOT_FOUND');
  assertZipError(() => readZipEntries(Buffer.alloc(0)), 'EOCD_NOT_FOUND');
});

test('read: rejects a truncated archive', () => {
  assertZipError(
    () => readZipEntries(CORRUPTION_ZIP.subarray(0, CORRUPTION_ZIP.length - 30)),
    'EOCD_NOT_FOUND',
  );
  assertZipError(() => readZipEntries(CORRUPTION_ZIP.subarray(0, 10)), 'EOCD_NOT_FOUND');
});

test('read: rejects a central directory beyond the file end', () => {
  const broken = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    copy.writeUInt32LE(0x7fffffff, CORRUPTION_STRUCTURE.eocd.offset + 12);
  });
  assertZipError(() => readZipEntries(broken), 'INVALID_CENTRAL_DIRECTORY');
});

test('read: rejects a central directory entry with a bad signature', () => {
  const broken = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    copy.writeUInt32LE(0, SECOND_HEADER.offset);
  });
  assertZipError(() => readZipEntries(broken), 'INVALID_CENTRAL_DIRECTORY');
});

test('read: rejects entry data outside the file', () => {
  const broken = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    copy.writeUInt32LE(CORRUPTION_ZIP.length + 4096, FIRST_HEADER.offset + 42);
  });
  assertZipError(() => readZipEntries(broken), 'ENTRY_OUT_OF_BOUNDS');
});

test('read: rejects an invalid local file header signature', () => {
  const broken = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    copy.writeUInt32LE(0, FIRST_HEADER.localHeaderOffset);
  });
  assertZipError(() => readZipEntries(broken), 'INVALID_LOCAL_HEADER');
});

test('read: reports a readable error when inflate fails', () => {
  assert.ok(FIRST_HEADER.compressedSize > 4, '测试前提：deflate 数据至少 4 字节');
  const payloadOffset = localPayloadOffset(CORRUPTION_ZIP, FIRST_HEADER);
  const broken = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    // 0xFF starts a deflate block with the reserved BTYPE=3, guaranteed invalid.
    copy.fill(0xff, payloadOffset, payloadOffset + 4);
  });
  assertZipError(() => readZipEntries(broken), 'INFLATE_FAILED', /解压|inflate/i);
});

test('read: rejects a decompressed size mismatch', () => {
  const broken = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    copy.writeUInt32LE(FIRST_HEADER.uncompressedSize + 1, FIRST_HEADER.offset + 24);
  });
  assertZipError(() => readZipEntries(broken), 'SIZE_MISMATCH');
});

// ---------------------------------------------------------------------------
// Decompression guards (zip bomb protection)
// ---------------------------------------------------------------------------

test('read: enforces entry-count, per-entry and total decompression limits', () => {
  const twoEntries = writeZipEntries([
    { name: 'a.txt', data: Buffer.from('a'.repeat(64)) },
    { name: 'b.txt', data: Buffer.from('b'.repeat(64)) },
  ]);
  assert.equal(readZipEntries(twoEntries).length, 2, '默认限额下正常档案必须仍可读');
  assertZipError(() => readZipEntries(twoEntries, { maxEntries: 1 }), 'TOO_MANY_ENTRIES', /压缩炸弹/u);
  assertZipError(() => readZipEntries(twoEntries, { maxEntryBytes: 32 }), 'ENTRY_TOO_LARGE', /压缩炸弹/u);
  assertZipError(
    () => readZipEntries(twoEntries, { maxEntryBytes: 100, maxTotalBytes: 100 }),
    'ARCHIVE_TOO_LARGE',
    /压缩炸弹/u,
  );
  // A nonsensical budget is rejected instead of silently reading with another one.
  assertZipError(() => readZipEntries(twoEntries, { maxEntryBytes: 0 }), 'INVALID_ARGUMENT', /maxEntryBytes/u);
  assertZipError(() => readZipEntries(twoEntries, { maxTotalBytes: 1.5 }), 'INVALID_ARGUMENT');
});

test('read: refuses a declared size beyond the default budget before inflating', () => {
  const bomb = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    // 1 GiB declared for a tiny payload: the default 512 MiB per-entry cap
    // trips from the central directory alone, before any inflate work.
    copy.writeUInt32LE(0x40000000, FIRST_HEADER.offset + 24);
  });
  assertZipError(() => readZipEntries(bomb), 'ENTRY_TOO_LARGE', /压缩炸弹/u);
});

test('read: a payload that inflates past its declared size cannot expand', () => {
  const lying = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    // Declare 8 bytes while the deflate payload inflates to the real 34-byte
    // content: bounded inflate must stop at the declared size.
    copy.writeUInt32LE(8, FIRST_HEADER.offset + 24);
  });
  assertZipError(() => readZipEntries(lying), 'SIZE_MISMATCH', /伪造|压缩炸弹/u);

  const emptyButNotEmpty = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    // A zero declared size must not read as "no output bound".
    copy.writeUInt32LE(0, FIRST_HEADER.offset + 24);
  });
  assertZipError(() => readZipEntries(emptyButNotEmpty), 'SIZE_MISMATCH');
});

test('read: exposes the default decompression budget', () => {
  assert.deepEqual(ZIP_READ_LIMITS, {
    maxEntries: 20_000,
    maxEntryBytes: 512 * 1024 * 1024,
    maxTotalBytes: 2 * 1024 * 1024 * 1024,
  });
  assert.ok(Object.isFrozen(ZIP_READ_LIMITS));
});

test('read: rejects an unsupported compression method', () => {
  const broken = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    copy.writeUInt16LE(12, FIRST_HEADER.offset + 10); // bzip2, unsupported
  });
  assertZipError(() => readZipEntries(broken), 'UNSUPPORTED_COMPRESSION', /压缩方法|compression/i);
});

test('read: rejects encrypted entries', () => {
  const broken = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    copy.writeUInt16LE(copy.readUInt16LE(FIRST_HEADER.offset + 8) | 0x0001, FIRST_HEADER.offset + 8);
  });
  assertZipError(() => readZipEntries(broken), 'ENCRYPTED_UNSUPPORTED', /加密/);
});

test('read: rejects ZIP64 markers in the EOCD and central directory', () => {
  const zip64Eocd = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    copy.writeUInt16LE(0xffff, CORRUPTION_STRUCTURE.eocd.offset + 10);
  });
  assertZipError(() => readZipEntries(zip64Eocd), 'ZIP64_UNSUPPORTED', /ZIP64/i);

  const zip64Entry = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    copy.writeUInt32LE(0xffffffff, FIRST_HEADER.offset + 20);
  });
  assertZipError(() => readZipEntries(zip64Entry), 'ZIP64_UNSUPPORTED', /ZIP64/i);
});

test('read: rejects multi-disk archives', () => {
  const broken = copyWithPatches(CORRUPTION_ZIP, (copy) => {
    copy.writeUInt16LE(1, CORRUPTION_STRUCTURE.eocd.offset + 4);
  });
  assertZipError(() => readZipEntries(broken), 'MULTI_DISK_UNSUPPORTED', /分卷/);
});

test('read: every failure is an Error with a non-empty readable message', () => {
  const cases = [
    Buffer.from('definitely not a zip file'),
    CORRUPTION_ZIP.subarray(0, CORRUPTION_ZIP.length - 10),
  ];
  for (const bytes of cases) {
    assert.throws(() => readZipEntries(bytes), (error) => {
      assert.ok(error instanceof Error);
      assert.ok(!(error instanceof String));
      assert.equal(typeof error.message, 'string');
      assert.ok(error.message.length > 5);
      assert.ok(!error.message.includes('[object Object]'));
      return true;
    });
  }
});
